pub fn fresh_evidence_x(mut holes: Strings, mut named: Strings) -> List<&'static Rpe> {
    loop {
        if null_p(holes) {
            return nil::<&'static Rpe>();
        } else if (not(has_prefix_p(car(holes), str_lit("'"))) || string_member_p(car(holes), named)) {
            holes = cdr(holes);
            continue;
        } else {
            let k = get(fresh_regions());
            set(fresh_regions(), i64_plus(k, 1i64));
            return kayak_rt::heap_cons(rpe(car(holes), kayak_rt::heap_cons(Product_11_12_13_14_15(int_lit(0), symbol_lit(str_lit("evidence")), false, nil::<Symbol>(), kayak_rt::heap_cons(the::<RpOperand>(kayak_rt::heap_alloc(Sum_4node_5bound_4hole_5const_3sym_3int_4flag::<Int, Product_11_12<Int, Int>, Int, Product_11_12_13<Str, Int, Str>, Symbol, Int, bool>::Node(int_lit(1)))), kayak_rt::nil())), kayak_rt::heap_cons(Product_11_12_13_14_15(int_lit(1), symbol_lit(str_lit("rconst")), false, nil::<Symbol>(), kayak_rt::heap_cons(the::<RpOperand>(kayak_rt::heap_alloc(Sum_4node_5bound_4hole_5const_3sym_3int_4flag::<Int, Product_11_12<Int, Int>, Int, Product_11_12_13<Str, Int, Str>, Symbol, Int, bool>::Sym(string_to_symbol(string_append(str_lit("%region-"), i64_to_string(k)))))), kayak_rt::nil())), kayak_rt::nil())), nil::<Symbol>()), fresh_evidence_x(cdr(holes), named));
        }
    }
}

/// Rep `rep`'s binary form, its holes filled from the evidence `given`
/// holds, for the variables `names` names: canonical, each set's members
/// once.
pub fn rep_filled_x(rep: i64, given: i64, names: Str) -> Bytes {
    let got = (&rep_nodes)(word_kfx_bytes(rep), nil::<Str>());
    let main = rexp(got.0, map(lambda1s(move |y: Symbol| {
        symbol_to_string(y)
    }), got.1), int_lit(0), str_lit(""));
    let named = spaced_words(names);
    let es = onto(evidence_given(given, named, 1i64), fresh_evidence_x(map(lambda1s(move |y: Symbol| {
        symbol_to_string(y)
    }), got.1), named));
    let canonical = lambda1s(move |r: &'static Rexp| {
        let tagcase_ = r;
        match *tagcase_ {
            Rexp::Rexp(ns, hs, root, d) => {
                the::<Bytes>(rep_of_nodes(ns, map(lambda1s(move |h: Str| {
                    string_to_symbol(h)
                }), hs), root))
            }
        }
    });
    let b = canonical(rp_filled(main, es));
    let again = (&rep_nodes)(b, nil::<Str>());
    canonical(rexp(map(lambda1s(move |x: RpNode| {
        if x.2 {
            Product_11_12_13_14_15(x.0, x.1, true, x.3, rp_once(x.4))
        } else {
            x
        }
    }), again.0), map(lambda1s(move |y: Symbol| {
        symbol_to_string(y)
    }), again.1), int_lit(0), str_lit("")))
}

// `(%reify given REP names)`: evidence, its rep filled.
pub fn reify_run_x(given: i64, rep: i64, names: i64) -> i64 {
    kfx_bytes_word_x(rep_filled_x(rep, given, word_string(names)))
}

/// `(%stage-run m code given rep names)`: `(sum ok THUNK)`, the code made a
/// procedure over module `m`, checked against `rep` filled from the
/// evidence given (C307); or `(sum failed WHY)`.
pub fn stage_run_x(m: i64, code: i64, given: i64, rep: i64, names: i64) -> i64 {
    let t = (&rep_ty)(rep_filled_x(rep, given, word_string(names)));
    let thunk = staged_thunk(code_sexp_x(code));
    let prog = staged_program(thunk);
    let why = stage_worked(prog, t);
    if not(string_eq_p(why, str_lit(""))) {
        refused_word_x(why)
    } else {
        let s = stage_checked(prog, t);
        let gs = with_entries({
            let tagcase_ = s;
            match *tagcase_ {
                St::St(sbs, k, fs, ns) => {
                    fs
                }
            }
        });
        let body = lower(thunk, kayak_rt::heap_cons(kayak_rt::heap_cons(str_lit("stage-module"), kayak_rt::nil()), kayak_rt::nil()), gs);
        let l = number_x(body);
        let e = alloc_x(ob_env(), 2i64);
        let p = alloc_x(ob_proc(), 2i64);
        slot_set_x(e, 0i64, w_nil());
        slot_set_x(e, 1i64, m);
        slot_set_x(p, 0i64, code_word(l));
        slot_set_x(p, 1i64, e);
        sum_word_x(str_lit("ok"), p)
    }
}

// Sessions (C310; Fixpt's `docs/fx26.md`, "Sessions", and its
// `sessions.rs`, lowered): definitions that last between pieces of code a
// program stages against a module. A session's state is the checker's
// environment of the standard one and the session's own definitions, its
// globals, past the program's, and its definitions' forms, which the
// redefinition rules of the `--check` driver (C202) read: a definition
// again at a type its users can take assigns its global; at another,
// `shadow` makes it a new one, what used the old keeping it, and `rerun`
// checks the users again, each that checks run again, the rest broken.
// The session, a vector `#(m index)`, names its state by its index here,
// made at its first use, when the module's type is known: a global holding
// `m`, and one for each of `m`'s values, which the session's own may
// shadow; defined again as a new global, `fx26-session-K:NAME:2`, ... (C313).
// A pending definition is `#(session index)`, its index among
// `pendings`. Reading a session's global is reading the session, which its
// forms' types say (`(read r)`), not part of the code's `E`: the checker's
// `%session` mark (`naming-effs`).
pub enum Defn {
    Defn(Strings, &'static Sexp),
}

pub fn defn(f0: Strings, f1: &'static Sexp) -> &'static Defn {
    kayak_rt::heap_alloc(Defn::Defn(f0, f1))
}

pub type Defns = List<&'static Defn>;

pub enum RerunOut {
    RerunOut(&'static Cv, Strings),
}

pub fn rerun_out(f0: &'static Cv, f1: Strings) -> &'static RerunOut {
    kayak_rt::heap_alloc(RerunOut::RerunOut(f0, f1))
}

pub fn defn_names(d: &'static Defn) -> Strings {
    let tagcase_ = d;
    match *tagcase_ {
        Defn::Defn(ns, f) => {
            ns
        }
    }
}

/// The globals a top-level form defines: a `define`'s, a `define*`'s, a
/// `define-rec`'s.
pub fn defined_names_of(f: &'static Sexp) -> Strings {
    if ((head_is_p(f, str_lit("define")) || head_is_p(f, str_lit("define*"))) && i64_gt_eq(size(items(f)), 3i64) && not(module_def_p(f))) {
        kayak_rt::heap_cons(binder_name(second(items(f))), kayak_rt::nil())
    } else if head_is_p(f, str_lit("define-rec")) {
        map(lambda1s(move |g: &'static Sexp| {
            binder_name(car(items(g)))
        }), cdr(items(f)))
    } else {
        nil::<Str>()
    }
}

/// Whether a global of `names`, defined before, is now at a type its uses
/// may not take.
pub fn rerun_needed_p(old: &'static Cv, new: &'static Cv, names: Strings) -> bool {
    any_p(lambda1s(move |n: Str| {
        let (a, b) = (scope_bind(n, old), scope_bind(n, new));
        (not(null_p(a)) && not(null_p(b)) && {
            let tagcase_ = car(a);
            match *tagcase_ {
                Bind::Bind(n1, sa, wa) => {
                    ((string_eq_p(wa, str_lit("global")) || string_eq_p(wa, str_lit("broken"))) && {
                        let tagcase_ = car(b);
                        match *tagcase_ {
                            Bind::Bind(n2, sb, wb) => {
                                not((string_eq_p(scheme_text(sa), scheme_text(sb)) || narrower_effect_p(sb, sa)))
                            }
                        }
                    })
                }
            }
        })
    }), names)
}

/// The definitions among `ds` that use a name of `used`, and those that
/// use theirs, oldest first.
pub fn users_of(mut ds: Defns, mut used: Strings) -> Defns {
    loop {
        if null_p(ds) {
            return nil::<&'static Defn>();
        } else if {
            let tagcase_ = car(ds);
            match *tagcase_ {
                Defn::Defn(ns, f) => {
                    any_p(lambda1s(move |n: Str| {
                        string_member_p(n, used)
                    }), names_in(f))
                }
            }
        } {
            return kayak_rt::heap_cons(car(ds), users_of(cdr(ds), onto(defn_names(car(ds)), used)));
        } else {
            ds = cdr(ds);
            continue;
        }
    }
}

pub fn broken_binds(v: &'static Cv, names: Strings) -> Binds {
    concat(map(lambda1s(move |n: Str| {
        let b = scope_bind(n, v);
        if null_p(b) {
            nil::<&'static Bind>()
        } else {
            let tagcase_ = car(b);
            match *tagcase_ {
                Bind::Bind(m, sc, w) => {
                    the::<Binds>(kayak_rt::heap_cons(bind(n, sc, str_lit("broken")), kayak_rt::nil()))
                }
            }
        }
    }), names))
}

