/// The index of the session's global named `n`, the newest; -1 if none.
pub fn sglobal_of(mut gl: Sglobals, mut n: Str) -> i64 {
    loop {
        if null_p(gl) {
            return -1i64;
        } else if {
            let tagcase_ = car(gl);
            match *tagcase_ {
                Sglobal::Sglobal(m, i) => {
                    string_eq_p(m, n)
                }
            }
        } {
            let tagcase_ = car(gl);
            match *tagcase_ {
                Sglobal::Sglobal(m, i) => {
                    return i;
                }
            }
        } else {
            gl = cdr(gl);
            continue;
        }
    }
}

/// The name of the session's global `i` if it is its name's newest; ``
/// if not, or none.
pub fn sglobal_name(mut gl: Sglobals, mut all: Sglobals, mut i: i64) -> Str {
    loop {
        if null_p(gl) {
            return str_lit("");
        } else if {
            let tagcase_ = car(gl);
            match *tagcase_ {
                Sglobal::Sglobal(m, j) => {
                    i64_eq(i, j)
                }
            }
        } {
            let tagcase_ = car(gl);
            match *tagcase_ {
                Sglobal::Sglobal(m, j) => {
                    if i64_eq(sglobal_of(all, m), i) {
                        return m;
                    } else {
                        return str_lit("");
                    }
                }
            }
        } else {
            gl = cdr(gl);
            continue;
        }
    }
}

/// The globals' names a session's code is lowered with: the program's
